import sys,os;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('git-blame'),GD('git-bisect'),GD('git-log','Git – git-log (-S, --graph)'),GD('giteveryday','Git – giteveryday (Everyday Git)'),GD('gittutorial','Git – gittutorial'),('https://docs.gitlab.com/user/project/merge_requests/','GitLab Docs – Merge requests'),('https://www.odoo.com/documentation/20.0/contributing/development/git_guidelines.html','Odoo 20 – Git guidelines')])
CHECK='python3 -c "import sys;sys.path.insert(0,\'models\');from utils import price_per_hour;sys.exit(0 if price_per_hour(4500000, 24) == 187500 else 1)"\n'
def dia(vi):
    t=('Một chu kỳ làm việc trọn vẹn với Git và GitLab' if vi else 'A complete work cycle with Git and GitLab','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g12'%('vi' if vi else 'en'))
    P='Bài' if vi else 'Part'
    row1=[(['Nhận issue'],['Take issue'],'%s 3'%P),(['Commit'],['Commit'],'%s 2, 10'%P),(['Push + MR'],['Push + MR'],'%s 4, 5'%P),(['Review + CI'],['Review + CI'],'%s 5, 11'%P)]
    row2=[(['Merge, dọn'],['Merge, clean'],'%s 5'%P),(['Tag'],['Tag'],'%s 9'%P),(['Hotfix'],['Hotfix'],'%s 9'%P),(['Truy vết'],['Trace bugs'],'%s 12'%P)]
    b=''
    for row,y in ((row1,15),(row2,115)):
        for i,(tv,te,sub) in enumerate(row):
            x=4+i*166
            b+='<rect class="%s" x="%d" y="%d" width="134" height="60" rx="12" />\n<text class="dg-title" x="%d" y="%d">%s</text><text class="dg-text" x="%d" y="%d">%s</text>\n'%('dg-accent' if (row is row1 and i==2) else 'dg-box',x,y,x+14,y+26,(tv if vi else te)[0],x+14,y+46,sub)
            if i<3: b+='<path class="dg-arrow" d="M%d %d h22 m-8 -6 l8 6 l-8 6" />\n'%(x+137,y+30)
    b+='<path class="dg-arrow" d="M569 75 V95 H71 V113 m-6 -8 l6 8 l6 -8" />\n'
    return fig('640 190',t[0],b,t[1],t[2])
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a12');base(sb);sb.q('echo __pycache__/ >> .git/info/exclude')
    BN='GIT_AUTHOR_NAME="Trần Thị Bình" GIT_AUTHOR_EMAIL=binh.tran@example.com GIT_COMMITTER_NAME="Trần Thị Bình" GIT_COMMITTER_EMAIL=binh.tran@example.com '
    sb.w('models/utils.py','def price_per_hour(price, hours):\n    return price / hours\n')
    sb.q('git add .;git commit -qm "[ADD] vinc_course: hàm giá theo giờ";git tag -a v1.0.0 -m "1.0.0"')
    sb.w('check.sh',CHECK);sb.q('mv check.sh $HOME/check.sh')
    steps=[('A','append','\n\ndef format_price(price):\n    return f"{price:,.0f} VND"\n','[IMP] vinc_course: thêm định dạng giá'),('B','file:README.md','# vinc_course\n','[ADD] vinc_course: README'),('A','append','\n\ndef is_free(price):\n    return price == 0\n','[IMP] vinc_course: thêm kiểm tra khóa miễn phí'),('B','sub',('price / hours','price * hours'),'[IMP] vinc_course: tối ưu price_per_hour'),('A','append','\n\ndef total_hours(courses):\n    return sum(c["hours"] for c in courses)\n','[IMP] vinc_course: thêm tổng số giờ'),('B','file:CHANGELOG.md','# 1.1.0\n','[ADD] vinc_course: changelog'),('A','append','\n\ndef hours_label(hours):\n    return f"{hours} giờ"\n','[IMP] vinc_course: thêm nhãn số giờ')]
    for who,kind,val,msg in steps:
        env=BN if who=='B' else ''
        if kind=='append': open(sb.cwd+'/models/utils.py','a').write(val)
        elif kind=='sub':
            pp=sb.cwd+'/models/utils.py';ss=open(pp).read();open(pp,'w').write(ss.replace(*val))
        else: open(sb.cwd+'/'+kind[5:],'w').write(val)
        sb.q(env+'git add -A;'+env+'git commit -qm "%s"'%msg)
    T1=sb.P('git log --oneline','git blame -L 1,3 models/utils.py','git blame -L :price_per_hour models/utils.py','git log -S"price * hours" --oneline')
    T2=sb.P('git bisect start','git bisect bad','git bisect good v1.0.0','git bisect run sh $HOME/check.sh','git bisect reset')
    T2b=sb.P('git show --stat --oneline 8cff483')
    c=SB('a12c');base(c);remote_setup(c)
    c.q('git tag -a v1.0.0 -m "1.0.0";git remote add origin git@gitlab.example.com:vinc/vinc_course.git;git push -q -u origin main 2>&1;git push -q origin v1.0.0')
    c.q('cd .. && git clone -q git@gitlab.example.com:vinc/vinc_course.git vinc_course_binh && cd vinc_course_binh && git config user.name "Trần Thị Bình" && git config user.email "binh.tran@example.com"')
    C1=c.P('cd ..','git clone git@gitlab.example.com:vinc/vinc_course.git vinc_course_an','cd vinc_course_an')
    c.q('git config user.name "Nguyễn Văn An";git config user.email an.nguyen@example.com')
    C2=c.P('git switch -c 21-course-code',"echo \"    code = fields.Char(string='Mã khóa')\" >> models/course.py",'git commit -am "[IMP] vinc_course: thêm mã khóa học" -m "Closes #21"')
    c.q('cd ../vinc_course_binh && echo "# vinc_course" > README.md && git add README.md && git commit -qm "[ADD] vinc_course: README" && git push -q')
    C3=c.P('git fetch','git rebase origin/main','git push -u origin 21-course-code')
    C4=c.P('# GitLab merge MR #21 (giả lập)','cd ../vinc_course_binh','git pull -q','git merge --no-ff origin/21-course-code -m "Merge branch \'21-course-code\' into \'main\'"','git push -q','cd ../vinc_course_an','git switch main','git pull -q','git branch -d 21-course-code','git push -q origin --delete 21-course-code','git fetch --prune')
    C5=c.P('git tag -a v1.1.0 -m "Phát hành 1.1.0"','git push origin v1.1.0','git switch -c hotfix/1.1.1 v1.1.0','sed -i "s/Mã khóa/Mã khóa học/" models/course.py','git commit -am "[FIX] vinc_course: nhãn mã khóa học đầy đủ"','git tag -a v1.1.1 -m "Hotfix 1.1.1"','git push -q origin v1.1.1','git switch main','git cherry-pick -x hotfix/1.1.1','git push -q','git branch -D hotfix/1.1.1','git log --oneline --graph --decorate -n 8')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Bài cuối giúp bạn tìm ra “ai và commit nào làm hỏng”, rồi ghép toàn bộ series thành một chu kỳ làm việc trọn vẹn.</strong> <code>git blame</code> cho biết mỗi dòng do commit nào sửa lần cuối, <code>git log -S</code> tìm commit đã thêm hay bớt một đoạn chữ, <code>git bisect run</code> tự dò nhị phân commit gây lỗi. Phần tổng hợp chạy thật quy trình: nhận issue, nhánh, commit, rebase, push, merge request, tag, hotfix và cherry-pick về <code>main</code>, kèm bảng tra cứu 12 bài.','<strong>The final part finds “who and which commit broke it”, then joins the whole series into one complete working cycle.</strong> <code>git blame</code> shows which commit last changed each line, <code>git log -S</code> finds the commit that added or removed a piece of text, and <code>git bisect run</code> binary-searches the culprit commit by itself. The capstone really runs the workflow: take an issue, branch, commit, rebase, push, merge request, tag, hotfix and cherry-pick back to <code>main</code>, with a cheat-sheet of all 12 parts.')))
    o+=h2('blame',t('Truy dấu từng dòng: git blame và git log -S','Tracing line by line: git blame and git log -S'))
    o+=p(t('Khi một hàm trả kết quả sai, câu hỏi đầu tiên là “dòng này thêm vào từ khi nào, vì lý do gì?”. <code>git blame</code> in từng dòng kèm mã commit, tác giả và thời gian của lần sửa gần nhất; <code>-L</code> giới hạn phạm vi dòng hoặc theo tên hàm. Ở repo mẫu này hàm <code>price_per_hour</code> ban đầu chia giá cho số giờ, nhưng đồng nghiệp đã “tối ưu” nó. Blame chỉ ra thủ phạm ngay: dòng <code>return</code> thuộc commit của Bình, còn dòng <code>def</code> vẫn của An.','When a function returns a wrong result the first question is “since when is this line here, and why?”. <code>git blame</code> prints every line with the commit, author and time of its latest change; <code>-L</code> limits it to a line range or a function name. In this sample repo <code>price_per_hour</code> originally divided the price by the hours, but a colleague “optimised” it. Blame points straight at it: the <code>return</code> line belongs to Binh\'s commit while the <code>def</code> line is still An\'s.'))
    o+=p(t('Nếu chưa biết dòng nằm ở đâu, hãy tìm theo nội dung. <code>git log -S"chuỗi"</code> (kiểu “pickaxe”) liệt kê các commit làm số lần xuất hiện của chuỗi đó thay đổi, tức là thêm hoặc xóa nó:','If you do not know where the line is, search by content. <code>git log -S"text"</code> (the “pickaxe” style) lists the commits that changed how many times that text occurs, meaning they added or removed it:'))
    o+=T1
    o+=p(t('Blame cho biết commit <em>cuối cùng</em> đụng vào dòng, không phải lúc nào cũng là gốc của vấn đề: nếu ai đó chỉ sửa định dạng thì blame trỏ tới họ. Các cờ <code>-M</code> và <code>-C</code> theo dõi dòng được di chuyển hoặc sao chép giữa các file, còn <code>--ignore-rev</code> cho phép bỏ qua một commit định dạng hàng loạt. Dùng blame để <strong>hiểu bối cảnh và hỏi đúng người</strong>, không phải để đổ lỗi.','Blame reports the <em>last</em> commit that touched a line, which is not always the root of the problem: if someone only reformatted it, blame points at them. The <code>-M</code> and <code>-C</code> flags trace lines relocated or duplicated across files, and <code>--ignore-rev</code> lets you skip a bulk formatting commit. Use blame to <strong>understand context and ask the right person</strong>, not to assign blame.'))
    o+=h2('bisect',t('Dò nhị phân commit gây lỗi: git bisect','Binary-searching the culprit: git bisect'))
    o+=p(t('Khi bạn biết bản cũ chạy đúng (tag <code>v1.0.0</code>) và bản hiện tại sai, nhưng giữa chúng có hàng chục commit, <code>git bisect</code> giúp tìm ra commit đầu tiên gây lỗi bằng tìm kiếm nhị phân: mỗi bước nó chuyển bạn tới commit ở giữa khoảng còn nghi ngờ, bạn báo “tốt” hay “xấu”, và khoảng thu hẹp một nửa. Với 1.000 commit chỉ cần khoảng 10 bước. Bạn có thể tự bấm <code>good</code>/<code>bad</code>, hoặc giao cho một script: theo tài liệu, <code>git bisect run</code> gọi script ở mỗi bước và hiểu mã thoát 0 là tốt, 1–127 (trừ 125) là xấu, 125 là bỏ qua commit không kiểm tra được, còn mã khác sẽ hủy quá trình.','When you know an older version worked (tag <code>v1.0.0</code>) and the current one is wrong, but dozens of commits lie between them, <code>git bisect</code> finds the first bad commit by binary search: at each step it takes you to the commit halfway through the suspect range, you say “good” or “bad”, and the range halves. 1,000 commits take only about 10 steps. You can press <code>good</code>/<code>bad</code> yourself or hand it a script: per the documentation, <code>git bisect run</code> calls the script at each step and reads exit code 0 as good, 1–127 (except 125) as bad, 125 as “cannot test this commit, skip it”, and any other code aborts the process.'))
    o+=p(t('Script kiểm tra của chúng ta chỉ kiểm tra đúng một điều: giá 4.500.000 chia 24 giờ phải bằng 187.500. Nó nằm ngoài repo (để bisect đổi commit mà không làm mất nó):','Our test script checks exactly one thing: a price of 4,500,000 over 24 hours must equal 187,500. It lives outside the repo so bisect can switch commits without losing it:'))
    o+=pre(CHECK)
    o+=T2
    o+=p(t('Chỉ ba bước kiểm tra trên bảy commit, Git kết luận <code>8cff483</code> là commit đầu tiên gây lỗi, và ta xem nội dung của nó bằng <code>git show</code>. Nhớ chạy <code>git bisect reset</code> để quay về nhánh đang làm việc:','In just three checks across seven commits Git concludes <code>8cff483</code> is the first bad commit, and we read it with <code>git show</code>. Remember <code>git bisect reset</code> to return to your working branch:'))
    o+=T2b
    o+=p(t('Điều kiện để bisect hiệu quả là <strong>mỗi commit đều chạy được độc lập</strong>, đúng lời khuyên “chia thành các bước nhỏ, nhất quán” của tài liệu <code>gitworkflows</code> ở bài 10. Một lịch sử đầy commit hỏng giữa chừng sẽ làm bisect phải bỏ qua nhiều bước.','For bisect to be effective, <strong>every commit must work on its own</strong>, exactly the “small, consistent steps” advice of the <code>gitworkflows</code> document from part 10. A history full of half-broken commits forces bisect to skip many steps.'))
    o+=h2('tong-hop',t('Dự án tổng hợp: một chu kỳ làm việc trọn vẹn','Capstone: one complete working cycle'))
    o+=p(t('Giờ ghép các bài thành một ngày làm việc. An nhận issue #21 “thêm mã khóa học”, làm trên nhánh riêng, đẩy lên GitLab, MR được duyệt và merge, nhóm gắn tag 1.1.0; sau đó phát hiện nhãn chưa đẹp ở bản đang chạy nên làm hotfix 1.1.1 và đưa về <code>main</code>. Mỗi bước tương ứng một bài của series:','Now we join the parts into a working day. An takes issue #21 “add a course code”, works on a dedicated branch, pushes to GitLab, the MR is approved and merged and the team tags 1.1.0; then a label problem is found in the running version so a hotfix 1.1.1 is made and brought back to <code>main</code>. Each step maps to a part of the series:'))
    o+=dia(vi)
    o+=p(t('<strong>Bước 1–2. Lấy repo, tạo nhánh theo issue, commit đúng quy ước</strong> (bài 2, 3, 4, 10):','<strong>Steps 1–2. Get the repo, branch by issue, commit with the convention</strong> (parts 2, 3, 4, 10):'))
    o+=C1+C2
    o+=p(t('<strong>Bước 3. Cập nhật nhánh theo <code>main</code> rồi push</strong> (bài 4, 8). Trong lúc An làm, Bình đã đẩy README lên <code>main</code>, nên An fetch và rebase nhánh của mình lên đó trước khi đẩy:','<strong>Step 3. Bring the branch up to date with <code>main</code> and push</strong> (parts 4, 8). While An worked, Binh pushed a README to <code>main</code>, so An fetches and rebases the branch onto it before pushing:'))
    o+=C3
    o+=p(t('<strong>Bước 4. Merge request được duyệt, merge, dọn nhánh</strong> (bài 5). Bình đóng vai GitLab, rồi An cập nhật <code>main</code> và xóa nhánh đã xong:','<strong>Step 4. The merge request is approved, merged and the branch cleaned up</strong> (part 5). Binh plays GitLab, then An updates <code>main</code> and deletes the finished branch:'))
    o+=C4
    o+=p(t('<strong>Bước 5. Phát hành và hotfix</strong> (bài 9). Gắn tag, đẩy tag, tách hotfix từ tag, gắn tag bản vá và cherry-pick về <code>main</code>. Đồ thị cuối cùng kể lại cả câu chuyện:','<strong>Step 5. Release and hotfix</strong> (part 9). Tag, push the tag, branch the hotfix from the tag, tag the patch and cherry-pick it to <code>main</code>. The final graph tells the whole story:'))
    o+=C5
    o+=p(t('Cách học nhanh nhất là tự dựng lại kịch bản trên một repo thử. Năm bài tập gợi ý:','The fastest way to learn is to rebuild the scenario yourself on a scratch repo. Five suggested exercises:'))
    o+=ul([t('Tạo một repo bare làm “GitLab” (<code>git init --bare</code>) và clone hai bản để tự đóng vai An và Bình.','Create a bare repo to act as “GitLab” (<code>git init --bare</code>) and clone it twice to play both An and Binh.'),t('Cố tình tạo một xung đột trong <code>__manifest__.py</code> rồi giải quyết bằng cả merge lẫn rebase.','Deliberately create a conflict in <code>__manifest__.py</code> and resolve it with both merge and rebase.'),t('Viết hook <code>commit-msg</code> của riêng bạn và thử bỏ qua nó bằng <code>--no-verify</code>.','Write your own <code>commit-msg</code> hook and try skipping it with <code>--no-verify</code>.'),t('Gắn tag, tách hotfix từ tag và cherry-pick về nhánh chính.','Tag a release, branch a hotfix from it and cherry-pick it to the main branch.'),t('Gài một lỗi vào giữa lịch sử rồi dùng <code>git bisect run</code> tự tìm ra nó.','Plant a bug in the middle of history and let <code>git bisect run</code> find it by itself.')])
    o+=h2('cheat-sheet',t('Bảng tra cứu nhanh cả series','A cheat-sheet for the whole series'))
    o+=tbl([t('Tình huống','Situation'),t('Lệnh','Command'),t('Bài','Part')],[
        [t('Cấu hình lần đầu','First-time setup'),'<code>git config --global user.name / user.email</code>','1'],
        [t('Xem trạng thái, thay đổi','Status and changes'),'<code>git status -s</code>, <code>git diff</code>, <code>git diff --staged</code>','2'],
        [t('Lưu một commit','Make a commit'),'<code>git add</code>, <code>git commit -m "[TAG] module: ..."</code>','2, 10'],
        [t('Làm việc trên nhánh','Branching'),'<code>git switch -c</code>, <code>git merge</code>, <code>git branch -d</code>','3'],
        [t('Đồng bộ với GitLab','Syncing with GitLab'),'<code>git clone</code>, <code>fetch</code>, <code>pull</code>, <code>push -u</code>','4'],
        [t('Gộp công việc','Joining work'),t('merge request; <code>git rebase main</code> khi cần','a merge request; <code>git rebase main</code> when needed'),'5, 8'],
        [t('Có xung đột','A conflict'),'<code>git add</code> + <code>git commit</code> / <code>git merge --abort</code>','6'],
        [t('Lỡ tay','Undoing a mistake'),'<code>restore</code>, <code>commit --amend</code>, <code>reset</code>, <code>revert</code>, <code>reflog</code>','7'],
        [t('Đang dở mà có việc gấp','Urgent work mid-task'),'<code>git stash push -m</code> / <code>pop</code>','9'],
        [t('Phát hành, sửa nóng','Release and hotfix'),'<code>git tag -a</code>, <code>cherry-pick -x</code>','9'],
        [t('Tự động kiểm tra','Automatic checks'),t('hook <code>pre-commit</code>, <code>.gitlab-ci.yml</code>','<code>pre-commit</code> hook, <code>.gitlab-ci.yml</code>'),'11'],
        [t('Tìm commit gây lỗi','Finding the bug-causing commit'),'<code>blame</code>, <code>log -S</code>, <code>bisect run</code>','12']])
    o+=h2('khi-ket',t('Khi Git báo lỗi lạ: bình tĩnh theo bốn bước','When Git shows a strange error: four calm steps'))
    o+=ul([t('<strong>Đọc hết thông báo, nhất là các dòng <code>hint:</code>.</strong> Git thường ghi sẵn lệnh nên chạy, như bạn đã thấy ở các bài trước.','<strong>Read the whole message, especially the <code>hint:</code> lines.</strong> Git often spells out the command to run, as you saw in earlier parts.'),t('<strong><code>git status</code></strong> cho biết bạn đang ở đâu: nhánh nào, có đang merge/rebase dở không, file nào chờ xử lý.','<strong><code>git status</code></strong> says where you are: which branch, whether a merge or rebase is in progress, which files await attention.'),t('<strong><code>git log --oneline --graph --all</code></strong> cho bức tranh lịch sử; kết hợp <code>--decorate</code> để thấy nhánh và tag.','<strong><code>git log --oneline --graph --all</code></strong> gives the picture of history; add <code>--decorate</code> to see branches and tags.'),t('<strong>Dừng lại trước khi dùng lệnh hủy diệt</strong> (<code>reset --hard</code>, <code>clean -f</code>, <code>push --force</code>). Tạo nhánh sao lưu, rồi nếu lỡ tay hãy nhờ <code>git reflog</code>.','<strong>Pause before any destructive command</strong> (<code>reset --hard</code>, <code>clean -f</code>, <code>push --force</code>). Create a backup branch, and if you slip use <code>git reflog</code>.')])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Script bisect không chạy được ở một số commit.</strong> Ví dụ import cả package <code>models</code> sẽ kéo theo <code>odoo</code> và lỗi ngay. Nếu script thoát với mã lỗi chung, Git coi commit đó là “xấu” và cho kết luận sai. Hãy kiểm tra script trên một commit tốt và một commit xấu trước, và trả mã 125 khi không thể kiểm tra.','<strong>The bisect script cannot run at some commits.</strong> Importing the whole <code>models</code> package, for instance, drags in <code>odoo</code> and fails at once. When the script ends with a generic error code Git counts that commit as “bad” and draws a wrong conclusion. Test the script on a known-good and a known-bad commit first, and return 125 when it cannot test.'),
        t('<strong>Quên <code>git bisect reset</code>.</strong> Bạn vẫn đang ở trạng thái bisect (HEAD tách rời). Chạy <code>git bisect reset</code> trước khi làm việc tiếp.','<strong>Forgetting <code>git bisect reset</code>.</strong> You are still in a bisect session (a detached HEAD). Run <code>git bisect reset</code> before carrying on.'),
        t('<strong>Dùng blame để đổ lỗi.</strong> Commit cuối cùng đụng vào dòng chưa chắc là nguyên nhân; hãy đọc <code>git show</code> của nó và hỏi người viết thay vì kết luận vội.','<strong>Using blame to assign guilt.</strong> The last commit to touch a line is not necessarily the cause; read its <code>git show</code> and ask the author rather than jumping to conclusions.'),
        t('<strong>Đổi bản trong lúc bisect mà còn sửa dở.</strong> Hãy commit hoặc stash (bài 9) trước khi <code>git bisect start</code> để không mất việc.','<strong>Switching versions during bisect with unfinished edits.</strong> Commit or stash (part 9) before <code>git bisect start</code> so nothing is lost.')])
    o+=h2('tong-ket',t('Tổng kết cả series','Summary of the whole series'))
    o+=ul([t('Nền tảng: ba vùng làm việc, commit nhỏ có lời nhắn tốt, <code>.gitignore</code> ngay từ đầu.','Foundations: the three areas, small commits with good messages, <code>.gitignore</code> from the start.'),t('Cộng tác: nhánh ngắn hạn, GitLab, merge request, xung đột và rebase đúng quy tắc.','Collaboration: short-lived branches, GitLab, merge requests, conflicts and rebase within the rules.'),t('An toàn: biết chọn lệnh hoàn tác, luôn có lưới <code>reflog</code> và nhánh sao lưu.','Safety: choose the right undo command, always keep the <code>reflog</code> and backup branches as a net.'),t('Phát hành: tag, hotfix từ tag, cherry-pick; hook và CI để máy kiểm tra thay con người.','Releasing: tags, hotfixes from tags, cherry-pick; hooks and CI so machines do the checking.'),t('Truy vết: <code>blame</code>, <code>log -S</code>, <code>bisect</code> để tìm nguyên nhân thay vì đoán.','Tracing: <code>blame</code>, <code>log -S</code> and <code>bisect</code> to find causes instead of guessing.')])
    o+=p(t('Bạn đã đi hết 12 bài, từ lệnh <code>git init</code> đầu tiên tới một quy trình nhóm có merge request, CI và phát hành. Bước tiếp theo tự nhiên là áp dụng ngay vào dự án thật: tạo repo GitLab cho module của bạn, bật nhánh bảo vệ và thêm file <code>.gitlab-ci.yml</code> đầu tiên. Nếu muốn cùng quay lại phần lập trình, hãy đọc tiếp <a href="../odoo/index.html">series Lập trình Odoo 20</a> và <a href="../python/index.html">series Python thực chiến</a>, hai series dùng chung dự án <code>vinc_course</code> với bài này.','You have gone through all 12 parts, from the very first <code>git init</code> to a team workflow with merge requests, CI and releases. The natural next step is to apply it to a real project: create a GitLab repo for your module, turn on branch protection and add your first <code>.gitlab-ci.yml</code>. If you want to return to coding, read on with the <a href="../odoo/index.html">Odoo 20 Development series</a> and the <a href="../python/index.html">Practical Python series</a>, which share the <code>vinc_course</code> project with this one.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
